// SPDX‑License‑Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";

contract FirmwareRegistry is Ownable {
    struct FirmwareInfo {
        string   version;      // e.g. "0x0102"
        string   cid;          // IPFS CID (encrypted firmware)
        bytes32  hash;         // SHA‑256 of clear firmware
        bytes    signature;    // ECDSA‑secp256k1 (65 bytes)
        bytes32  keyID;        // ID of AES‑GCM group‑key
        string   deviceType;   // board family
        uint256  timestamp;    // when published
        bool     removed;      // soft‑delete flag
    }

    mapping(string => FirmwareInfo) private _firmwares;  // version → info
    string[] private _versionIndex;

    /* events */
    event NewFirmware(
        string   indexed version,
        string   cid,
        bytes32  hash,
        bytes    signature,
        bytes32  keyID,
        string   deviceType,
        uint256  timestamp
    );

    event FirmwareRemoved(string indexed version, uint256 timestamp);

    /* owner‑only ---------------------------------------------------------- */

    function publishFirmware(
        string calldata version,
        string calldata cid,
        bytes32 hash_,
        bytes calldata signature,
        bytes32 keyID,
        string calldata deviceType
    ) external onlyOwner {
        require(bytes(version).length > 0, "empty version");
        require(bytes(cid).length > 0, "empty CID");
        require(_firmwares[version].timestamp == 0, "version exists");

        _firmwares[version] = FirmwareInfo(
            version,
            cid,
            hash_,
            signature,
            keyID,
            deviceType,
            block.timestamp,
            false
        );
        _versionIndex.push(version);

        emit NewFirmware(
            version, cid, hash_, signature, keyID, deviceType, block.timestamp
        );
    }

    function removeFirmware(string calldata version) external onlyOwner {
        FirmwareInfo storage fw = _firmwares[version];
        require(fw.timestamp != 0, "not found");
        require(!fw.removed, "already removed");
        fw.removed = true;
        emit FirmwareRemoved(version, block.timestamp);
    }

    /* views --------------------------------------------------------------- */

    function getFirmware(string calldata version)
        external
        view
        returns (FirmwareInfo memory)
    {
        return _firmwares[version];
    }

    function getAllFirmwares()
        external
        view
        returns (FirmwareInfo[] memory list)
    {
        uint256 n = _versionIndex.length;
        list = new FirmwareInfo[](n);
        for (uint256 i; i < n; ++i) {
            list[i] = _firmwares[_versionIndex[i]];
        }
    }
}
